// Tests the auto-fill rules production runs: the ones migration 000232 ships
// (generated by db/tools/gen_autofill_rules.py). They are read straight from
// that migration so a change to the rules that breaks a code fails here.
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { applyAutofillRules, autofillRuleError, codeLayoutError, parseCode } from './productAutofill'

const sql = readFileSync(resolve(process.cwd(), '../db/migrations/000232_autofill_new_code_layout.up.sql'), 'utf8')
const between = tag => sql.split(`$${tag}$`)[1]
const layout = between('layout')
const rules = JSON.parse(between('rules'))

const fill = (code, name = '') => applyAutofillRules(rules, { code, name }, layout).values
const pick = (values, ...keys) => Object.fromEntries(keys.map(k => [k, values[k]]))

describe('shipped rules are well formed', () => {
  it('the layout compiles and names its parts', () => {
    expect(codeLayoutError(layout)).toBe('')
  })
  it('every rule is one the Auto-fill Rules page would accept', () => {
    for (const r of rules) {expect(autofillRuleError(r), JSON.stringify(r)).toBe('')}
  })
  it('never fills the legacy Type field', () => {
    expect(rules.filter(r => r.field === 'type')).toEqual([])
  })
})

describe('the codes people actually enter', () => {
  it('EF6LJE10, from the bug report: lady jeans, outlet, 2026, price 10', () => {
    expect(fill('EF6LJE10')).toEqual({
      kind: 'Lady', origin: 'Outlet', year: '2026',
      category: 'Bottoms', subcategory: 'Jeans', price: '10',
    })
  })
  it('EOC5LSW25: outlet, lady sweater (Tops), 2025, price 25 -- any case', () => {
    const want = { kind: 'Lady', origin: 'Outlet', year: '2025', category: 'Tops', subcategory: 'Sweater', price: '25' }
    expect(fill('EOC5LSW25')).toEqual(want)
    expect(fill('eoc5lsw25')).toEqual(want)
  })
  it('older codes carry no price (CA21LSW) and fill no price', () => {
    const v = fill('CA21LSW')
    expect(pick(v, 'kind', 'origin', 'year', 'category', 'subcategory')).toEqual({
      kind: 'Lady', origin: 'Outlet', year: '2021', category: 'Tops', subcategory: 'Sweater',
    })
    expect(v.price).toBeUndefined()
  })
  it('month codes: CAJUL25KBPA22 is kids pants, outlet, price 22, and no fixed season', () => {
    const v = fill('CAJUL25KBPA22')
    expect(pick(v, 'kind', 'origin', 'year', 'category', 'subcategory', 'price')).toEqual({
      kind: 'Kids', origin: 'Outlet', year: '2025', category: 'Bottoms', subcategory: 'Pants', price: '22',
    })
    expect(v.season).toBeUndefined()
  })
  it('one-digit years: S is Set and B is Jacket (EF6LS14, EF6LB20)', () => {
    expect(pick(fill('EF6LS14'), 'category', 'subcategory')).toEqual({ category: 'Sets', subcategory: 'Set' })
    expect(pick(fill('EF6LB20'), 'category', 'subcategory')).toEqual({ category: 'Outerwear', subcategory: 'Jacket' })
  })
  it('two-digit years: S is Short (CA22LS10)', () => {
    expect(pick(fill('CA22LS10'), 'category', 'subcategory')).toEqual({ category: 'Bottoms', subcategory: 'Shorts' })
  })
  it.each([
    ['COC5BGJ7', 'China', 'Baby'],
    ['BOC5MJE9', 'Bangladesh', 'Men'],
    ['TM6KBSW12', 'Turkey', 'Kids'],
    ['N22LSW9', 'Bangladesh', 'Lady'],
    ['L22LSW9', 'Lebanon', 'Lady'],
  ])('%s -> %s, %s', (code, origin, kind) => {
    expect(pick(fill(code), 'origin', 'kind')).toEqual({ origin, kind })
  })
  it('Favori and Everywear brands come from the code', () => {
    expect(fill('FDC5LJ20').brand).toBe('Favori')
    expect(fill('RDC5340-BE').brand).toBe('Everywear')
  })
  it('outlet stock never gets a fixed season, other months do', () => {
    expect(fill('EF6LJE10').season).toBeUndefined()
    expect(fill('CAMAY25LTSH9').season).toBeUndefined()
    expect(fill('TMAY25LD10').season).toBe('Summer')
  })
  it('home goods are Home with no kind or year', () => {
    expect(fill('GO22123')).toEqual({ category: 'Home', subcategory: 'Home' })
  })
  it('model numbers are not prices or years', () => {
    expect(fill('T1178')).toEqual({ origin: 'Turkey' })
    expect(fill('TH989').year).toBeUndefined()
  })
  it('a bare year-and-model code (X24805) still gets origin and year', () => {
    expect(fill('X24805')).toEqual({ origin: 'China', year: '2024' })
  })
})

describe('the name fills what the code cannot', () => {
  it('a name alone fills kind, category and sub-category', () => {
    expect(fill('', 'Lady Winter Jacket')).toMatchObject({ kind: 'Lady', category: 'Outerwear', subcategory: 'Jacket', season: 'Winter' })
    expect(fill('', 'Kids Boy Sweatshirt')).toMatchObject({ kind: 'Kids', category: 'Tops', subcategory: 'Sweatshirt' })
    expect(fill('', 'Baby Girl Overall')).toMatchObject({ kind: 'Baby', category: 'Sets', subcategory: 'Overall & Romper' })
  })
  it('the code wins the garment, the name wins who it is for', () => {
    const v = fill('EF6LJE10', 'Men Jeans')
    expect(v.kind).toBe('Men')
    expect(pick(v, 'category', 'subcategory')).toEqual({ category: 'Bottoms', subcategory: 'Jeans' })
  })
  it('whole words only: sweatshirt is not a shirt, women is not men', () => {
    expect(fill('', 'Lady Sweatshirt').subcategory).toBe('Sweatshirt')
    expect(fill('', 'Women Pants').kind).toBe('Lady')
  })
  it('brands come from the name', () => {
    expect(fill('', 'Men Nike Shoes').brand).toBe('Nike')
  })
})

describe('every type token the rules know, built into a code (randomized)', () => {
  const tokenRules = field => rules.filter(r => r.match === 'part' && r.part === 'type' && r.field === field)
  const tokens = []
  for (const r of tokenRules('subcategory')) {
    const cat = tokenRules('category').find(c => c.pattern === r.pattern)
    for (const t of r.pattern.split('|')) {tokens.push({ token: t, sub: r.value, cat: cat.value })}
  }
  const audiences = [['BB', 'Baby'], ['BG', 'Baby'], ['KB', 'Kids'], ['KG', 'Kids'], ['JB', 'Kids'], ['JG', 'Kids'], ['L', 'Lady'], ['M', 'Men'], ['MX', 'Unisex']]
  const families = [['EF6', 'Outlet', '2026'], ['EOC5', 'Outlet', '2025'], ['CA21', 'Outlet', '2021'], ['CA24', 'Outlet', '2024'], ['COC5', 'China', '2025'], ['BOC5', 'Bangladesh', '2025'], ['OT21', 'China', '2021'], ['N23', 'Bangladesh', '2023']]

  // A small deterministic generator, so a failure reproduces.
  let seed = 7
  const rnd = n => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n }

  it('each token is listed once (first match wins, so a repeat would hide a rule)', () => {
    const seen = new Map()
    for (const { token, sub } of tokens) {
      expect(seen.has(token), `${token} listed twice`).toBe(false)
      seen.set(token, sub)
    }
  })

  it('fills kind, garment, origin, year and price from 600 generated codes', () => {
    // Tokens a one-digit-year family reads differently (S, B), or that start
    // with an audience letter so the audience would swallow them, are
    // covered by the explicit tests above.
    const plain = tokens.filter(t => !['S', 'B'].includes(t.token))
    for (let i = 0; i < 600; i++) {
      const { token, sub, cat } = plain[rnd(plain.length)]
      const [aud, kind] = audiences[rnd(audiences.length)]
      const [fam, origin, year] = families[rnd(families.length)]
      const price = 1 + rnd(99)
      const code = `${fam}${aud}${token}${price}`
      const parts = parseCode(layout, code)
      // The audience letters can swallow the type's first letter (L+... vs
      // LB...), which makes the split ambiguous; skip those, not the rule.
      if (parts.audience?.toUpperCase() !== aud || parts.type?.toUpperCase() !== token) {continue}
      const v = fill(code)
      expect(v, code).toMatchObject({ kind, origin, year, category: cat, subcategory: sub, price: String(price) })
    }
  })
})
